function handleThrow(mc)
{
   if(mc._x > 660 && mc._x < 685)
   {
      if(mc._y > 61 && mc._y < 93)
      {
         if(clocktower.tower._currentframe == 1)
         {
            clocktower.tower.play();
         }
         mc._visible = false;
      }
   }
}
function clockTimer()
{
   now.setTime(now.getTime() + 1000);
   ct_day = now.getDay();
   var _loc1_ = days_of_the_week[ct_day];
   clocktower.day_txt.text = _loc1_.toUpperCase();
   ct_hours = now.getHours();
   if(ct_hours > 11)
   {
      if(ct_hours > 12)
      {
         ct_hours -= 12;
      }
      pm_trigger = true;
   }
   else
   {
      if(ct_hours == 0)
      {
         ct_hours = 12;
      }
      pm_trigger = false;
   }
   if(pm_trigger == true)
   {
      clocktower.am_pm.text = "PM";
   }
   else
   {
      clocktower.am_pm.text = "AM";
   }
   ct_minutes = now.getMinutes();
   if(ct_minutes < 10)
   {
      ct_minutes = "0" + now.getMinutes();
   }
   clocktower.clock_txt.text = ct_hours + " : " + ct_minutes;
}
var ENGINE = _global.getCurrentEngine();
var INTERFACE = _global.getCurrentInterface();
var SHELL = _global.getCurrentShell();
var days_of_the_week = new Array(SHELL.getLocalizedString("sunday"),SHELL.getLocalizedString("monday"),SHELL.getLocalizedString("tuesday"),SHELL.getLocalizedString("wednesday"),SHELL.getLocalizedString("thursday"),SHELL.getLocalizedString("friday"),SHELL.getLocalizedString("saturday"));
var start_x = 480;
var start_y = 310;
var language;
var localized_frame = 1;
if(SHELL.getLocalizedFrame != undefined)
{
   localized_frame = SHELL.getLocalizedFrame();
}
switch(localized_frame)
{
   case 1:
      language = "english";
      break;
   case 2:
      language = "portuguese";
      break;
   case 3:
      language = "french";
      break;
   case 4:
      language = "spanish";
      break;
   default:
      language = "english";
}
background_mc.lang_superrink_mc.gotoAndStop(language);
clocktower.lang_timezone_mc.gotoAndStop(language);
clocktower.lang_G_mc.gotoAndStop(language);
triggers_mc.town_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("town",620,330);
};
triggers_mc.rink_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("rink",390,170);
};
triggers_mc.plaza_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("plaza",132,338);
};
clock_btn.onRelease = function()
{
   INTERFACE.showContent("clock_help");
};
triggers_mc._visible = false;
block_mc._visible = false;
timer = getTimer();
speedTimer = getTimer();
speed = 1000;
if(SHELL.getPenguinStandardTime != undefined)
{
   var now = SHELL.getPenguinStandardTime();
}
else
{
   var now = new Date();
}
clockTimer();
this.onEnterFrame = function()
{
   speedTimer = getTimer();
   if(speedTimer - timer >= speed)
   {
      timer = speedTimer;
      clockTimer();
   }
};
